//! KiCad's `newstroke` vector font, laid out and stroked as KiCad 9 does.
//!
//! KiCad's DRC tests the real stroked glyphs (`KIFONT::STROKE_FONT` + `TransformTextToPolySet`),
//! so this lays out the same Hershey polylines with KiCad's metrics and strokes each segment as a
//! round-ended capsule, using a solid padded box only when `knockout` is set. The glyph table
//! (`GLYPH_INDEX`, `GLYPH_DATA`) is KiCad 9.0.8's `newstroke`, read out of `libkicommon.so`.
//! Metres throughout, Y down.

const SCALE: f64 = 1.0 / 21.0;
const INTERLINE: f64 = 1.68 * 0.9583;
const ITALIC_TILT: f64 = 0.125;
const OVERBAR_HEIGHT: f64 = 1.23;
const OVERBAR_INSET: f64 = 0.1;
const TOFU: &[u8] = b"F^K[KFYFY[K[";
/// Chord sagitta cap for glyph stroke endcaps (1 um, finer than KiCad's 5 um `ARC_HIGH_DEF`).
const CAP_ERROR_M: f64 = 1e-6;

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum HAlign {
    Left,
    Center,
    Right,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum VAlign {
    Top,
    Center,
    Bottom,
}

#[derive(Debug, Clone, Copy)]
pub struct TextStyle {
    /// Glyph width and height in metres (`(size H W)` in the file has height first, width second).
    pub width: f64,
    pub height: f64,
    /// Explicit `(thickness T)` in metres, or `None` when omitted or zero.
    pub thickness: Option<f64>,
    pub bold: bool,
    pub italic: bool,
    pub h_align: HAlign,
    pub v_align: VAlign,
    pub mirror: bool,
    pub knockout: bool,
    /// `(line_spacing S)`: the pitch of lines, as a multiple of KiCad's own.
    pub line_spacing: f64,
}

/// Polygons of `text` placed at `anchor` and rotated by `angle_deg` in the caller's frame.
pub fn polygons(text: &str, anchor: [f64; 2], angle_deg: f64, style: &TextStyle) -> Vec<Vec<[f64; 2]>> {
    let (w, h) = (style.width, style.height);
    if w <= 0.0 || h <= 0.0 || text.is_empty() {
        return Vec::new();
    }
    let pen = effective_pen(w, h, style.thickness, style.bold);
    if pen <= 0.0 {
        return Vec::new();
    }
    // KiCad's `wxStringSplit` drops a single trailing newline without adding an empty line, while
    // two trailing newlines still add one.
    let trimmed = text.strip_suffix('\n').unwrap_or(text);
    let lines: Vec<&str> = trimmed.split('\n').collect();
    let interline = h * INTERLINE * style.line_spacing;
    let block_h = interline * (lines.len().saturating_sub(1)) as f64 + h * 1.17;
    let top_to_base0 = h - pen * 0.052;
    let y0 = match style.v_align {
        VAlign::Top => top_to_base0,
        VAlign::Bottom => top_to_base0 - block_h,
        VAlign::Center => top_to_base0 - block_h * 0.5,
    };
    let pad_x = pen / 1.52;
    let mut polylines: Vec<Vec<[f64; 2]>> = Vec::new();
    for (li, line) in lines.iter().enumerate() {
        let (adv_w, line_polys) = layout_line(line, w, h, style.italic);
        let x0 = match style.h_align {
            HAlign::Left => pad_x,
            HAlign::Right => -adv_w - pad_x,
            HAlign::Center => -adv_w * 0.5,
        };
        let yb = y0 + li as f64 * interline;
        for st in line_polys {
            polylines.push(st.into_iter().map(|[px, py]| [x0 + px, yb + py]).collect());
        }
    }
    if polylines.is_empty() {
        return Vec::new();
    }
    let xf = |[mut px, py]: [f64; 2]| {
        if style.mirror {
            px = -px;
        }
        place(anchor, angle_deg, [px, py])
    };
    let r = pen * 0.5;
    if style.knockout {
        let (mut x_min, mut y_min) = (f64::MAX, f64::MAX);
        let (mut x_max, mut y_max) = (f64::MIN, f64::MIN);
        for p in polylines.iter().flatten() {
            x_min = x_min.min(p[0]);
            y_min = y_min.min(p[1]);
            x_max = x_max.max(p[0]);
            y_max = y_max.max(p[1]);
        }
        let kpad = (h / 9.0).max(r);
        let (x0, x1) = (x_min - r - kpad, x_max + r + kpad);
        let (y0, y1) = (y_min - r - kpad, y_max + r + kpad);
        return vec![vec![xf([x0, y0]), xf([x1, y0]), xf([x1, y1]), xf([x0, y1])]];
    }
    let mut out = Vec::new();
    for st in polylines {
        if st.len() == 1 {
            out.push(dot(xf(st[0]), r));
        } else {
            for seg in st.windows(2) {
                out.push(stroke_capsule(xf(seg[0]), xf(seg[1]), r));
            }
        }
    }
    out
}

/// `local` turned by `rotation_deg` (counter-clockwise on screen) and moved to `at`.
fn place(at: [f64; 2], rotation_deg: f64, local: [f64; 2]) -> [f64; 2] {
    let (s, c) = rotation_deg.to_radians().sin_cos();
    let [x, y] = local;
    [at[0] + x * c + y * s, at[1] + y * c - x * s]
}

fn effective_pen(w: f64, h: f64, thickness: Option<f64>, bold: bool) -> f64 {
    let base = match thickness.filter(|&t| t > 0.0) {
        Some(t) => t,
        None if bold => w / 5.0,
        None => w / 8.0,
    };
    base.min(w.min(h) * 0.25)
}

fn layout_line(line: &str, w: f64, h: f64, italic: bool) -> (f64, Vec<Vec<[f64; 2]>>) {
    let mut x = 0.0_f64;
    let mut polys: Vec<Vec<[f64; 2]>> = Vec::new();
    let (space_adv, _) = decode_glyph(' ');
    let tab_w = 4.0 * space_adv * w;
    let mut chars = line.chars().peekable();
    let mut in_overbar = false;
    let mut obar_x0 = 0.0_f64;
    while let Some(ch) = chars.next() {
        if !in_overbar && ch == '~' && chars.peek() == Some(&'{') {
            chars.next();
            in_overbar = true;
            obar_x0 = x;
            continue;
        }
        if in_overbar && ch == '}' {
            in_overbar = false;
            let (bx0, bx1) = (obar_x0 + OVERBAR_INSET * w, x - OVERBAR_INSET * w);
            if bx1 > bx0 {
                let y = -OVERBAR_HEIGHT * h;
                polys.push(vec![[bx0, y], [bx1, y]]);
            }
            continue;
        }
        if ch == '\t' {
            if tab_w > 0.0 {
                x = ((x / tab_w + 1e-9).floor() + 1.0) * tab_w;
            }
            continue;
        }
        let (adv, strokes) = decode_glyph(ch);
        for st in strokes {
            polys.push(
                st.into_iter()
                    .map(|[gx, gy]| {
                        let tilt = if italic { ITALIC_TILT * gy * h } else { 0.0 };
                        [x + gx * w - tilt, gy * h]
                    })
                    .collect(),
            );
        }
        x += adv * w;
    }
    if in_overbar {
        let (bx0, bx1) = (obar_x0 + OVERBAR_INSET * w, x - OVERBAR_INSET * w);
        if bx1 > bx0 {
            let y = -OVERBAR_HEIGHT * h;
            polys.push(vec![[bx0, y], [bx1, y]]);
        }
    }
    (x, polys)
}

fn decode_glyph(ch: char) -> (f64, Vec<Vec<[f64; 2]>>) {
    let cp = ch as u32;
    let raw = u16::try_from(cp)
        .ok()
        .and_then(|key| GLYPH_INDEX.binary_search_by_key(&key, |&(k, _, _)| k).ok())
        .map(|i| {
            let (_, start, len) = GLYPH_INDEX[i];
            &GLYPH_DATA[start as usize..start as usize + len as usize]
        })
        .unwrap_or(TOFU);
    if raw.len() < 2 {
        return (0.0, Vec::new());
    }
    let left = (raw[0] as i16 - b'R' as i16) as f64 * SCALE;
    let right = (raw[1] as i16 - b'R' as i16) as f64 * SCALE;
    let adv = right - left;
    let mut strokes = Vec::new();
    let mut cur = Vec::new();
    let mut i = 2;
    while i + 1 < raw.len() {
        let (c0, c1) = (raw[i], raw[i + 1]);
        i += 2;
        if c0 == b' ' && c1 == b'R' {
            if !cur.is_empty() {
                strokes.push(std::mem::take(&mut cur));
            }
        } else {
            let gx = (c0 as i16 - b'R' as i16) as f64 * SCALE - left;
            let gy = (c1 as i16 - b'Z' as i16) as f64 * SCALE;
            cur.push([gx, gy]);
        }
    }
    if !cur.is_empty() {
        strokes.push(cur);
    }
    (adv, strokes)
}

fn cap_steps(r: f64, sweep: f64) -> usize {
    let step = 2.0 * (1.0 - (CAP_ERROR_M / r).min(1.0)).acos();
    ((sweep.abs() / step.max(1e-3)).ceil() as usize).max(4)
}

fn outside(r: f64, step: f64) -> f64 {
    r / (step * 0.5).cos()
}

fn dot(c: [f64; 2], r: f64) -> Vec<[f64; 2]> {
    let n = cap_steps(r, std::f64::consts::TAU).max(8);
    let ro = outside(r, std::f64::consts::TAU / n as f64);
    (0..n)
        .map(|k| {
            let a = std::f64::consts::TAU * k as f64 / n as f64;
            [c[0] + ro * a.cos(), c[1] + ro * a.sin()]
        })
        .collect()
}

fn stroke_capsule(a: [f64; 2], b: [f64; 2], r: f64) -> Vec<[f64; 2]> {
    let (dx, dy) = (b[0] - a[0], b[1] - a[1]);
    if dx.hypot(dy) == 0.0 {
        return dot(a, r);
    }
    let base = dy.atan2(dx);
    let n = cap_steps(r, std::f64::consts::PI);
    let ro = outside(r, std::f64::consts::PI / n as f64);
    let mut out = Vec::with_capacity(2 * (n + 1));
    for (c, from) in [(b, base - std::f64::consts::FRAC_PI_2), (a, base + std::f64::consts::FRAC_PI_2)] {
        for k in 0..=n {
            let t = from + std::f64::consts::PI * k as f64 / n as f64;
            out.push([c[0] + ro * t.cos(), c[1] + ro * t.sin()]);
        }
    }
    out
}
